import React, { useState, useMemo } from 'react';
import {
  Box,
  Chip,
  IconButton,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TablePagination,
  TableRow,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import ArrowBackIosNewIcon from '@mui/icons-material/ArrowBackIosNew';
import AccountBalanceWalletOutlinedIcon from '@mui/icons-material/AccountBalanceWalletOutlined';
import LocalShippingOutlinedIcon from '@mui/icons-material/LocalShippingOutlined';
import ReceiptLongOutlinedIcon from '@mui/icons-material/ReceiptLongOutlined';
import TrendingUpOutlinedIcon from '@mui/icons-material/TrendingUpOutlined';
import { useNavigate, useParams } from 'react-router';
import {
  useGetAllSupplierCreditHistoryQuery,
  useGetUserQuery,
} from '../posApi';
import { IUserInfo } from '../../core/Interface/user.interface';
import { ISupplierPaymentData } from '../../core/Interface/supplier.interface';
import { HEADER_GRADIENT } from '../../theme/appColors';
import {
  formatDate,
  getPriceFormatWithoutCurrency,
  getPriceFormat,
} from '../../core/utils';

const StatCard = ({
  icon,
  label,
  value,
  accent,
}: {
  icon: React.ReactNode;
  label: string;
  value: string;
  accent: string;
}) => (
  <Box
    sx={{
      alignItems: 'center',
      background: `linear-gradient(145deg, rgba(255,255,255,0.98) 0%, ${alpha(accent, 0.07)} 100%)`,
      border: `1px solid ${alpha(accent, 0.2)}`,
      borderRadius: '10px',
      display: 'flex',
      flex: 1,
      gap: 1.5,
      minWidth: 0,
      p: 2,
    }}
  >
    <Box
      sx={{
        alignItems: 'center',
        background: alpha(accent, 0.12),
        borderRadius: '8px',
        color: accent,
        display: 'flex',
        flexShrink: 0,
        height: 40,
        justifyContent: 'center',
        width: 40,
      }}
    >
      {icon}
    </Box>
    <Box sx={{ minWidth: 0 }}>
      <Typography sx={{ color: alpha('#142352', 0.5), fontSize: '0.7rem', fontWeight: 600, letterSpacing: '0.06em', textTransform: 'uppercase' }}>
        {label}
      </Typography>
      <Typography sx={{ color: '#142352', fontSize: '0.95rem', fontWeight: 800, lineHeight: 1.2, mt: 0.25, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
        {value}
      </Typography>
    </Box>
  </Box>
);

const headerCellSx = {
  background: '#F8FAFC',
  borderBottom: '2px solid #E2E8F0',
  color: alpha('#142352', 0.55),
  fontSize: '0.72rem',
  fontWeight: 700,
  letterSpacing: '0.06em',
  py: 1.5,
  textTransform: 'uppercase' as const,
  whiteSpace: 'nowrap' as const,
};

const CreditManage: React.FC = () => {
  const [page, setPage] = useState(0);
  const navigate = useNavigate();
  const { id: urlCreditId } = useParams();
  const [rowsPerPage, setRowsPerPage] = useState(10);

  const { data: creditData } = useGetAllSupplierCreditHistoryQuery(urlCreditId!, {
    skip: !urlCreditId,
  });

  const supplierList = useMemo(
    () => (creditData?.data ?? []) as ISupplierPaymentData[],
    [creditData?.data]
  );

  const { data: companyData } = useGetUserQuery();

  const currencyCode = useMemo(() => {
    if (companyData?.data) {
      const userData = companyData.data as IUserInfo;
      if (userData.company.currencyCode) return userData.company.currencyCode;
    }
    return '';
  }, [companyData]);

  const totalBalance = useMemo(
    () => supplierList.reduce((sum, item) => sum + (item.balance ?? 0), 0),
    [supplierList]
  );

  const totalAmountPaid = useMemo(
    () => supplierList.reduce((sum, item) => sum + (item.amountPaid ?? 0), 0),
    [supplierList]
  );

  const totalNetTotal = useMemo(
    () => supplierList.reduce((sum, item) => sum + (item.netTotal ?? 0), 0),
    [supplierList]
  );

  const handleChangePage = (_: unknown, newPage: number) => setPage(newPage);
  const handleChangeRowsPerPage = (e: React.ChangeEvent<HTMLInputElement>) => {
    setRowsPerPage(+e.target.value);
    setPage(0);
  };

  const supplierName = supplierList[0]?.supplierNameOrMobile ?? '—';
  const isCredit = totalBalance <= 0;

  const pagedRows = supplierList.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage);

  return (
    <Box>
      {/* Header */}
      <Box
        sx={{
          background: HEADER_GRADIENT,
          mb: 3,
          overflow: 'hidden',
          position: 'relative',
          px: 3,
          py: 2.5,
        }}
      >
        {/* Decorative circles */}
        <Box sx={{ background: 'rgba(255,255,255,0.06)', borderRadius: '50%', height: 200, pointerEvents: 'none', position: 'absolute', right: -60, top: -80, width: 200 }} />
        <Box sx={{ background: 'rgba(255,255,255,0.04)', borderRadius: '50%', height: 160, pointerEvents: 'none', position: 'absolute', left: '50%', top: -100, width: 160 }} />

        <Box sx={{ alignItems: 'center', display: 'flex', gap: 2, position: 'relative' }}>
          <IconButton
            onClick={() => navigate(-1)}
            size="small"
            sx={{
              background: 'rgba(255,255,255,0.12)',
              border: '1px solid rgba(255,255,255,0.2)',
              color: '#fff',
              flexShrink: 0,
              '&:hover': { background: 'rgba(255,255,255,0.2)' },
            }}
          >
            <ArrowBackIosNewIcon sx={{ fontSize: 16 }} />
          </IconButton>

          <Box
            sx={{
              alignItems: 'center',
              background: 'rgba(255,255,255,0.14)',
              borderRadius: '10px',
              display: 'flex',
              flexShrink: 0,
              height: 44,
              justifyContent: 'center',
              width: 44,
            }}
          >
            <LocalShippingOutlinedIcon sx={{ color: '#fff', fontSize: 22 }} />
          </Box>

          <Box sx={{ flex: 1, minWidth: 0 }}>
            <Typography sx={{ color: '#fff', fontSize: { xs: '1rem', md: '1.15rem' }, fontWeight: 800, letterSpacing: '-0.02em', lineHeight: 1.2 }}>
              Supplier Credit History
            </Typography>
            <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.78rem', fontWeight: 500, mt: 0.25 }}>
              {supplierName}
            </Typography>
          </Box>

          <Chip
            label={
              isCredit
                ? `Settled ${getPriceFormatWithoutCurrency(Math.abs(totalBalance))}`
                : `Due ${getPriceFormatWithoutCurrency(Math.abs(totalBalance))}`
            }
            size="small"
            sx={{
              background: isCredit ? 'rgba(22,163,74,0.22)' : 'rgba(220,38,38,0.22)',
              border: `1px solid ${isCredit ? 'rgba(22,163,74,0.4)' : 'rgba(220,38,38,0.4)'}`,
              color: isCredit ? '#86efac' : '#fca5a5',
              flexShrink: 0,
              fontWeight: 700,
              fontSize: '0.78rem',
            }}
          />
        </Box>
      </Box>

      <Box sx={{ px: 3 }}>
        {/* Stat cards */}
        <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1.5, mb: 3 }}>
          <StatCard
            accent="#0EA5E9"
            icon={<ReceiptLongOutlinedIcon sx={{ fontSize: 20 }} />}
            label="Total Records"
            value={String(supplierList.length)}
          />
          <StatCard
            accent="#8B5CF6"
            icon={<TrendingUpOutlinedIcon sx={{ fontSize: 20 }} />}
            label="Net Total"
            value={getPriceFormat(totalNetTotal, currencyCode)}
          />
          <StatCard
            accent="#22C55E"
            icon={<AccountBalanceWalletOutlinedIcon sx={{ fontSize: 20 }} />}
            label="Amount Paid"
            value={getPriceFormat(totalAmountPaid, currencyCode)}
          />
          <StatCard
            accent={isCredit ? '#16a34a' : '#dc2626'}
            icon={<AccountBalanceWalletOutlinedIcon sx={{ fontSize: 20 }} />}
            label="Outstanding Balance"
            value={getPriceFormatWithoutCurrency(Math.abs(totalBalance))}
          />
        </Box>

        {/* Table */}
        <Paper
          sx={{
            border: '1px solid #E2E8F0',
            borderRadius: '12px',
            boxShadow: 'none',
            mb: 3,
            overflow: 'hidden',
          }}
        >
          <TableContainer>
            <Table sx={{ minWidth: 700 }}>
              <TableHead>
                <TableRow>
                  <TableCell sx={{ ...headerCellSx, pl: 3, width: 48 }}>#</TableCell>
                  <TableCell sx={headerCellSx}>Receipt No</TableCell>
                  <TableCell sx={headerCellSx}>Date</TableCell>
                  <TableCell align="right" sx={headerCellSx}>Sub Total</TableCell>
                  <TableCell align="right" sx={headerCellSx}>Net Total</TableCell>
                  <TableCell align="right" sx={headerCellSx}>Discount</TableCell>
                  <TableCell align="right" sx={headerCellSx}>Amount Paid</TableCell>
                  <TableCell align="right" sx={{ ...headerCellSx, pr: 3 }}>Balance</TableCell>
                </TableRow>
              </TableHead>

              <TableBody>
                {pagedRows.length === 0 ? (
                  <TableRow>
                    <TableCell align="center" colSpan={8} sx={{ py: 6 }}>
                      <Typography sx={{ color: alpha('#142352', 0.35), fontWeight: 600 }}>
                        No payment records found
                      </Typography>
                    </TableCell>
                  </TableRow>
                ) : (
                  pagedRows.map((row, index) => {
                    const isDebit = row.balance > 0;
                    const rowNum = page * rowsPerPage + index + 1;
                    return (
                      <TableRow
                        key={index}
                        sx={{
                          '&:last-child td': { borderBottom: 0 },
                          '&:hover': { background: alpha('#0EA5E9', 0.03) },
                          transition: 'background 0.15s',
                        }}
                      >
                        <TableCell sx={{ color: alpha('#142352', 0.4), fontSize: '0.78rem', fontWeight: 600, pl: 3 }}>
                          {rowNum}
                        </TableCell>
                        <TableCell sx={{ fontSize: '0.82rem', fontWeight: 600, color: '#142352', maxWidth: 160, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                          {row.receiptNo}
                        </TableCell>
                        <TableCell sx={{ color: alpha('#142352', 0.65), fontSize: '0.82rem', whiteSpace: 'nowrap' }}>
                          {formatDate(new Date(row.dateTime))}
                        </TableCell>
                        <TableCell align="right" sx={{ color: alpha('#142352', 0.75), fontSize: '0.82rem' }}>
                          {row.subTotal === 0
                            ? getPriceFormatWithoutCurrency(row.subTotal)
                            : getPriceFormat(row.subTotal, currencyCode)}
                        </TableCell>
                        <TableCell align="right" sx={{ color: alpha('#142352', 0.75), fontSize: '0.82rem' }}>
                          {row.netTotal === 0
                            ? getPriceFormatWithoutCurrency(row.netTotal)
                            : getPriceFormat(row.netTotal, currencyCode)}
                        </TableCell>
                        <TableCell align="right" sx={{ color: alpha('#142352', 0.75), fontSize: '0.82rem' }}>
                          {row.totalDiscountAmount === 0
                            ? getPriceFormatWithoutCurrency(row.totalDiscountAmount)
                            : getPriceFormat(row.totalDiscountAmount, currencyCode)}
                        </TableCell>
                        <TableCell align="right" sx={{ color: '#16a34a', fontSize: '0.82rem', fontWeight: 600 }}>
                          {row.amountPaid === 0
                            ? getPriceFormatWithoutCurrency(row.amountPaid)
                            : getPriceFormat(row.amountPaid, currencyCode)}
                        </TableCell>
                        <TableCell align="right" sx={{ pr: 3 }}>
                          <Chip
                            label={getPriceFormatWithoutCurrency(Math.abs(row.balance))}
                            size="small"
                            sx={{
                              background: isDebit ? alpha('#dc2626', 0.08) : alpha('#16a34a', 0.08),
                              border: `1px solid ${isDebit ? alpha('#dc2626', 0.2) : alpha('#16a34a', 0.2)}`,
                              color: isDebit ? '#dc2626' : '#16a34a',
                              fontWeight: 700,
                              fontSize: '0.75rem',
                            }}
                          />
                        </TableCell>
                      </TableRow>
                    );
                  })
                )}
              </TableBody>
            </Table>
          </TableContainer>

          <Box sx={{ borderTop: '1px solid #E2E8F0' }}>
            <TablePagination
              component="div"
              count={supplierList.length}
              onPageChange={handleChangePage}
              onRowsPerPageChange={handleChangeRowsPerPage}
              page={page}
              rowsPerPage={rowsPerPage}
              rowsPerPageOptions={[5, 10, 25]}
              sx={{ '& .MuiTablePagination-toolbar': { px: 3 } }}
            />
          </Box>
        </Paper>
      </Box>
    </Box>
  );
};

export default CreditManage;
